import subprocess, time, urllib.request, urllib.error, urllib.parse

def req(path):
    url = f'http://127.0.0.1:8027{path}'
    try:
        with urllib.request.urlopen(url, timeout=3) as resp:
            return resp.status, resp.read().decode('utf-8', errors='replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8', errors='replace')

srv = subprocess.Popen(['node', 'server.js'])
try:
    ok = False
    for _ in range(30):
        try:
            status, body = req('/greet?name=Alice')
            ok = True
            break
        except (urllib.error.URLError, ConnectionResetError):
            time.sleep(0.5)
    assert ok, 'server never became reachable on :8027'
    assert status == 200 and 'Hello, Alice!' in body, f'legitimate input broken: {status} {body!r}'

    payload = '<script>alert(1)</script>'
    status, body = req('/greet?name=' + urllib.parse.quote(payload))
    assert status == 200, f'expected 200, got {status}'
    assert '<script>alert(1)</script>' not in body, f'unescaped script tag reflected back verbatim (XSS): {body!r}'
    assert '<script' not in body.lower(), f'a live <script tag is still present in the response: {body!r}'

    payload2 = '"><img src=x onerror=alert(2)>'
    status, body = req('/greet?name=' + urllib.parse.quote(payload2))
    assert status == 200
    assert '<img src=x onerror=alert(2)>' not in body, f'unescaped HTML injection reflected back verbatim: {body!r}'
finally:
    srv.terminate()
    try:
        srv.wait(timeout=5)
    except Exception:
        srv.kill()
print('PASS')

reference_solution.server.js:
const express = require('express');
const app = express();

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

app.get('/greet', (req, res) => {
  const name = req.query.name || 'stranger';
  res.send(`<h1>Hello, ${escapeHtml(name)}!</h1>`);
});

app.listen(8027);
